import time

def retry(func, n):
    for i in range(n):
        try:
            return func()
        except Exception:
            time.sleep(1)
    return None

final_output:
import time
import random

def retry(func, n):
    for i in range(n):
        try:
            return func()
        except Exception:
            time.sleep(2 ** i + random.uniform(0, 1))
    return None

